def min_window_substring(s, t):
    if not t or not s:
        return ""

    t_counts = {}
    for char in t:
        t_counts[char] = t_counts.get(char, 0) + 1

    required = len(t_counts)

    left = 0
    formed = 0
    window_counts = {}

    min_len = float('inf')
    min_window = (0, 0)

    for right in range(len(s)):
        char = s[right]
        window_counts[char] = window_counts.get(char, 0) + 1

        if char in t_counts and window_counts[char] == t_counts[char]:
            formed += 1

        while left <= right and formed == required:
            if right - left + 1 < min_len:
                min_len = right - left + 1
                min_window = (left, right)

            left_char = s[left]
            window_counts[left_char] -= 1
            if left_char in t_counts and window_counts[left_char] < t_counts[left_char]:
                formed -= 1

            left += 1

    if min_len == float('inf'):
        return ""

    return s[min_window[0]:min_window[1]+1]
