def min_window_substring(s: str, t: str) -> str:
    if not t or not s:
        return ""

    need = {}
    for char in t:
        need[char] = need.get(char, 0) + 1

    missing = len(t)
    left = 0
    best_start = 0
    best_len = float('inf')

    for right, char in enumerate(s):
        if char in need:
            if need[char] > 0:
                missing -= 1
            need[char] -= 1

        while missing == 0:
            if right - left + 1 < best_len:
                best_start = left
                best_len = right - left + 1

            removed_char = s[left]
            if removed_char in need:
                need[removed_char] += 1
                if need[removed_char] > 0:
                    missing += 1
            left += 1

    return s[best_start:best_start + best_len] if best_len != float('inf') else ""
